package com.bank.incident;

import com.bank.incident.service.IncidentResponder;
import com.bank.incident.service.TransferService;
import java.util.logging.*;

// Runnable demo: a disciplined response to a payment outage (pool exhaustion).
public class IncidentDemo {
    private static final Logger log = Logger.getLogger("Incident");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        TransferService transfers = new TransferService(log, 10); // pool max = 10
        IncidentResponder responder = new IncidentResponder(log, transfers);

        // Simulate a retry storm: 25 transfer attempts flood the 10-connection pool.
        for (int i = 0; i < 25; i++) transfers.attemptTransfer("SAV2001", "CUR3001");

        // Run the incident lifecycle.
        responder.handleIncident();
    }
}
