package com.bank.incident.service;

import java.util.logging.*;

// Performs transfers and tracks DB connection-pool usage (the exhaustion source).
public class TransferService {
    private final Logger log;
    private final int poolMax;
    private int activeConnections = 0;
    private boolean circuitOpen = false;   // circuit breaker to stabilize
    private int maxRetries = Integer.MAX_VALUE; // the root-cause bug: unbounded retries

    public TransferService(Logger log, int poolMax) {
        this.log = log;
        this.poolMax = poolMax;
    }

    public void attemptTransfer(String from, String to) {
        if (circuitOpen) return;                 // stabilized: reject fast
        if (activeConnections < poolMax) {
            activeConnections++;                 // grab a connection
        } else {
            // Unbounded retries pile up and keep the pool saturated.
            log.fine(() -> "Retry: no connection free (active=" + activeConnections + ")");
        }
    }

    public int getActive() { return activeConnections; }
    public int getPoolMax() { return poolMax; }
    public boolean isSaturated() { return activeConnections >= poolMax; }

    public void openCircuit() { circuitOpen = true; }
    public void capRetries(int max) { this.maxRetries = max; }
    public int getMaxRetries() { return maxRetries; }
    public void drainPool() { activeConnections = 0; } // release after fix
}
